    // End transition after 1 second
    if (_time > 1) {
        [_displayLink removeFromRunLoop:[NSRunLoop mainRunLoop] forMode:NSDefaultRunLoopMode];
    }
    else {
        _dissolvedCIImage = [self dissolveFilterImage:_sourceCIImage
                                                  to:_finalCIImage
                                              atTime:_time];

